# R/fct_casos.R -- carga dos casos e das malhas, compartilhada entre sessoes
# ==================================================================================
# No Shiny Server todas as sessoes do painel (cada usuario que abre a pagina)
# rodam no mesmo processo R. Casos, obitos so-SIM e malhas sao carregados uma
# vez por processo e reaproveitados por toda sessao nova (carrega_casos(),
# carrega_obitos_orfaos(), malha_*()); os casos recarregam sozinhos quando o
# cache muda no disco (botao "Atualizar dados").
#
# Cada caso tambem ja' sai com o bairro e o Distrito Sanitario onde o ponto
# cai (atribui_territorio()), gravados no cache por update_tb_data(): os
# indicadores por territorio contam por essas colunas em vez de refazer o
# cruzamento espacial territorios x casos a cada clique.
# ==================================================================================

cache_processo <- new.env(parent = emptyenv())

# Guarda em cache_processo o resultado de `expr` na primeira chamada; as
# seguintes (inclusive de outras sessoes) devolvem o mesmo objeto.
memo_processo <- function(chave, expr) {
  if (is.null(cache_processo[[chave]])) cache_processo[[chave]] <- force(expr)
  cache_processo[[chave]]
}

caminho_shape <- function(arquivo) {
  app_sys("app/www/shapes", arquivo)
}

# Limite do municipio de Recife, SIRGAS 2000 / UTM 25S
limite_municipio <- function() {
  memo_processo("limite_municipio", {
    sf::st_read(caminho_shape("recife.gpkg"), quiet = TRUE) |> sf::st_transform(31985)
  })
}

# 94 bairros do IBGE, malha completa -- usada em todo calculo.
malha_bairros <- function() {
  memo_processo("malha_bairros", {
    if (file.exists("local/bairros_cache.rds")) {
      readRDS("local/bairros_cache.rds")
    } else {
      bair <- sf::st_read(caminho_shape("bairros_recife.gpkg"), quiet = TRUE) |> sf::st_transform(31985)
      saveRDS(bair, "local/bairros_cache.rds")
      bair
    }
  })
}

# Distritos Sanitarios, gerados por dev/build_distritos_sanitarios.R: cada DS
# e' a uniao dos bairros do IBGE que a SESAU atribui a ele (limites iguais
# aos dos bairros do mapa; pop = soma do Censo 2022 dos bairros).
malha_distritos <- function() {
  memo_processo("malha_distritos", {
    sf::st_read(caminho_shape("distritos_sanitarios_recife.gpkg"), quiet = TRUE) |> sf::st_transform(31985)
  })
}

# Areas de abrangencia da APS, geradas por dev/build_abrangencia_aps.R a
# partir da territorializacao oficial da SESAU no ESIG (uma area por
# USF/USF+/EACS, mais areas descobertas e "nao se aplica").
malha_abrangencia <- function() {
  memo_processo("malha_abrangencia", {
    sf::st_read(caminho_shape("abrangencia_aps_recife.gpkg"), quiet = TRUE)
  })
}

# Bairros e DS SO' PRO DESENHO do indicador no mapa, simplificados a 5 m de
# tolerancia -- o poligono do indicador e' reenviado a cada troca de filtro,
# periodo ou indicador. Nenhum calculo usa essas versoes.
malha_bairros_desenho <- function() {
  memo_processo("malha_bairros_desenho", {
    sf::st_simplify(malha_bairros(), dTolerance = 5, preserveTopology = TRUE)
  })
}

malha_distritos_desenho <- function() {
  memo_processo("malha_distritos_desenho", {
    sf::st_simplify(malha_distritos(), dTolerance = 5, preserveTopology = TRUE)
  })
}

# DS de cada bairro (mesma ordem de malha_bairros()) -- ponto interno do
# bairro dentro do poligono do DS. Usado pra somar os obitos so-SIM, que so'
# tem o nome do bairro, por DS.
ds_de_cada_bairro <- function() {
  memo_processo("ds_de_cada_bairro", {
    pontos <- sf::st_point_on_surface(sf::st_geometry(malha_bairros()))
    ds <- malha_distritos()
    idx <- sf::st_intersects(pontos, ds)
    ds$cod_ds[vapply(idx, function(i) if (length(i) > 0) i[1] else NA_integer_, integer(1))]
  })
}

# Centroide de cada bairro, usado como localizacao aproximada dos obitos por
# TB que so' aparecem no SIM (sem endereco/coordenada propria).
centroides_bairros <- function() {
  memo_processo("centroides_bairros", {
    bair <- malha_bairros()
    sf::st_sf(
      bairro_norm = stringi::stri_trans_general(toupper(trimws(bair$name_neighborhood)), "Latin-ASCII"),
      geometry = sf::st_geometry(suppressWarnings(sf::st_centroid(bair)))
    )
  })
}

# Bairro (territorio_bairro, name_neighborhood) e Distrito Sanitario
# (territorio_ds, cod_ds) onde o ponto de cada caso cai, na malha completa.
# NA = sem coordenada ou fora dos poligonos. Um ponto exatamente na divisa
# entre dois territorios fica no primeiro deles (o st_intersects() que os
# indicadores faziam antes contava nos dois).
atribui_territorio <- function(casos) {
  primeiro <- function(idx) vapply(idx, function(i) if (length(i) > 0) i[1] else NA_integer_, integer(1))

  bair <- malha_bairros()
  casos$territorio_bairro <- bair$name_neighborhood[primeiro(sf::st_intersects(casos, bair))]

  ds <- malha_distritos()
  casos$territorio_ds <- ds$cod_ds[primeiro(sf::st_intersects(casos, ds))]

  casos
}

# tb_sinan_treated (DuckDB) -> casos do painel: datas, pontos em SIRGAS 2000 /
# UTM 25S (caso sem coordenada vira ponto vazio), listas de comorbidade/
# populacao especial como texto, dias em aberto e territorio
# (atribui_territorio()). Usado pra gerar local/casos_cache.rds
# (update_tb_data()) e na carga direta do DuckDB quando o cache nao existe.
prepara_casos <- function(casos_raw) {
  casos_raw <- casos_raw |>
    dplyr::as_tibble() |>
    dplyr::mutate(
      dt_diagnostico = as.Date(dt_diagnostico, format = "%d/%m/%Y"),
      dt_notificacao = as.Date(dt_notificacao, format = "%d/%m/%Y")
    )

  last_date <- max(casos_raw$dt_notificacao, na.rm = TRUE)

  casos_raw |>
    # na.fail = FALSE: caso sem coordenada vira ponto vazio em vez de
    # derrubar o cache inteiro (fica fora do mapa e dos indicadores por
    # territorio, mas continua nos cards e na tabela de casos)
    sf::st_as_sf(coords = c("long", "lat"), crs = 4674, na.fail = FALSE) |>
    sf::st_transform(31985) |>
    dplyr::mutate(
      desfecho = dplyr::case_when(
        situacao == "Em aberto" & is.na(desfecho) ~ "Em aberto",
        TRUE ~ desfecho
      )
    ) |>
    dplyr::rowwise() |>
    dplyr::mutate(
      comorbidades       = paste(comorbidades, collapse = ", "),
      populacao_especial = paste(populacao_especial, collapse = ", "),
      tempo_aberto = dplyr::case_when(
        situacao == "Encerrado" ~ as.integer(difftime(dt_encerramento, dt_diagnostico, units = "days")),
        TRUE                    ~ as.integer(difftime(last_date,       dt_diagnostico, units = "days"))
      )
    ) |>
    dplyr::ungroup() |>
    atribui_territorio()
}

# Casos do painel, compartilhados entre as sessoes do processo. Le'
# local/casos_cache.rds (ou, sem ele, o DuckDB) so' na primeira chamada ou
# quando o arquivo muda.
carrega_casos <- function() {
  arq <- "local/casos_cache.rds"
  versao <- if (file.exists(arq)) file.mtime(arq) else "sem cache"

  if (!is.null(cache_processo$casos) && identical(cache_processo$casos_versao, versao)) {
    return(cache_processo$casos)
  }

  casos <- if (file.exists(arq)) {
    readRDS(arq)
  } else {
    con <- DBI::dbConnect(duckdb::duckdb(), "local/sinan.duckdb", read_only = TRUE)
    on.exit(DBI::dbDisconnect(con, shutdown = TRUE), add = TRUE)
    prepara_casos(DBI::dbGetQuery(con, "select * from tb_sinan_treated"))
  }

  # Cache gerado antes da coluna `indicador` (vinda da pipeline de
  # georreferenciamento) existir: recria pela regra antiga
  # (POP_LIBER/POP_RUA) ate' o proximo update_tb_data().
  if (!"indicador" %in% names(casos)) {
    casos$indicador <- ifelse(grepl("Privado de liberdade|Situação de rua", casos$populacao_especial), 0L, 1L)
  }

  # Cache gerado antes do territorio ir pro cache (versao anterior do
  # update_tb_data()) -- calcula aqui, uma vez por processo.
  if (!all(c("territorio_bairro", "territorio_ds") %in% names(casos))) {
    casos <- atribui_territorio(casos)
  }

  cache_processo$casos <- casos
  cache_processo$casos_versao <- versao
  casos
}

# Obitos por TB so' no SIM (sem notificacao SINAN), compartilhados entre as
# sessoes. Nao sao "casos" (sem forma clinica, sem data de diagnostico, sem
# tratamento) -- alimentam so' os indicadores de mortalidade (card e mapa).
carrega_obitos_orfaos <- function() {
  arq <- "local/obitos_sim_orfaos_cache.rds"
  versao <- if (file.exists(arq)) file.mtime(arq) else if (file.exists("local/sinan.duckdb")) file.mtime("local/sinan.duckdb") else "sem base"

  if (!is.null(cache_processo$orfaos) && identical(cache_processo$orfaos_versao, versao)) {
    return(cache_processo$orfaos)
  }

  vazio <- dplyr::tibble(
    numerodo_do_sim = character(), dt_obito_sim = as.Date(character()),
    causabas_sim = character(), obito_tb_confirmado = logical(),
    bairro_norm = character()
  )

  orfaos <- if (file.exists(arq)) {
    readRDS(arq)
  } else if (file.exists("local/sinan.duckdb")) {
    con <- DBI::dbConnect(duckdb::duckdb(), "local/sinan.duckdb", read_only = TRUE)
    on.exit(DBI::dbDisconnect(con, shutdown = TRUE), add = TRUE)
    if ("tb_sim_orfaos_treated" %in% DBI::dbListTables(con)) {
      DBI::dbGetQuery(con, "SELECT * FROM tb_sim_orfaos_treated") |> dplyr::as_tibble()
    } else {
      vazio
    }
  } else {
    vazio
  }

  cache_processo$orfaos <- orfaos
  cache_processo$orfaos_versao <- versao
  orfaos
}

 .rt-td, .rt-tr-group {
  overflow: visible !important;
}

.rt-tr-group:hover {
  z-index: 9999 !important;
  position: relative; /* This 'activates' the z-index */
}

 /* Styling the ID part to look interactive */
.id-trigger {
  font-weight: bold;
  text-decoration: underline dotted;
  cursor: help;
  position: relative; /* Essential for positioning the tooltip */
}

/* Creating the Tooltip Box */
.id-trigger::after {
  content: attr(data-tooltip); /* Pulls text from the data-tooltip attribute */
  position: absolute;
  left: 50%;
  transform: translateX(-50%);
  background-color: #333;
  color: #fff;
  z-index: 10000;
  padding: 5px 10px;
  border-radius: 4px;
  white-space: nowrap;
  font-size: 0.8rem;
  font-weight: normal;
  visibility: hidden; /* Hidden by default */
  opacity: 0;
  transition: opacity 0.3s;
}

/* Showing the Tooltip on Hover */
.id-trigger:hover::after {
  visibility: visible;
  opacity: 1;
}

/* ==========================================================================
   Identidade visual dos paineis do Programa Cenarios
   (guia "Documentacao -- ID visual para paineis", cenarios.unb.br).
   Tokens copiados do bloco "CSS / Variaveis" do guia -- as mesmas cores
   ficam em R (cores_cen / cores_desfecho em R/mod_municipio.R e o tema em
   R/utils_app_theme.R).
   ========================================================================== */
:root {
  --cen-azul: #3891C0;
  --cen-azul-acao: #0E7BA8;
  --cen-azul-texto: #00638C;
  --cen-terra: #B67355;
  --cen-terra-texto: #8C4A2A;
  --cen-azul-fundo: #E6F1F7;
  --cen-terra-fundo: #F6EBE5;
  --cen-tinta: #12222B;
  --cen-tinta-2: #4A4A4A;
  --cen-tinta-3: #7A8B95;
  --cen-linha: #D8E3EA;
  --cen-fundo: #F2F6F9;
  --cen-superficie: #FFFFFF;
  --cen-ok: #1F6F4A;
  --cen-atencao: #8A6100;
  --cen-grave: #C24B12;
  --cen-critico: #A32235;
  --cen-s1: #3891C0; --cen-s2: #C0663C; --cen-s3: #6C5CA8; --cen-s4: #5A9E2E;
  --cen-s5: #8E3B46; --cen-s6: #B08A1E; --cen-s7: #3F4E9E; --cen-s8: #1B9AAA;

  /* Excecao pedida pela equipe de Recife: navy (cor tema de Recife) nas
     barras estrategicas -- cabecalho e barras de titulo das caixas (vem
     tambem do "primary" do tema em R/utils_app_theme.R) */
  --recife-navy: #12346B;
}

/* Tipografia: DM Sans 400 no corpo, rotulos e tabelas (14-15 px / 1.55) */
body,
.content-wrapper,
.leaflet-container,
.reactable,
.modal-content {
  font-family: 'DM Sans', 'Helvetica Neue', Arial, sans-serif;
  font-size: 15px;
  line-height: 1.55;
  color: var(--cen-tinta-2);
}

/* Poppins 700 nos titulos, azul titulos */
h1, h2, h3, h4,
.card-title,
.modal-title {
  font-family: 'Poppins', 'Helvetica Neue', Arial, sans-serif;
  font-weight: 700 !important;
  color: var(--cen-azul-texto);
}

/* Titulo do painel ("Panorama geral"): 28-36 px / 1.2 */
.content-wrapper h1 {
  font-size: 32px;
  line-height: 1.2;
}

/* Titulos de secao (blocos do mapa, titulo do mapa): 20-24 px / 1.3 */
.content-wrapper h3 {
  font-size: 22px;
  line-height: 1.3;
}

/* Numeros tabulares em qualquer coluna/valor numerico */
.reactable,
.rt-table,
.small-box .inner h3,
.info.legend,
.leaflet-tooltip {
  font-variant-numeric: tabular-nums;
}

/* Cabecalho em navy de Recife (barra estrategica). O guia diz que, dentro
   do WordPress, a faixa azul/cabecalho vem do template do site -- este
   painel mantem cabecalho proprio, em navy, a pedido da equipe de Recife. */
.main-header.navbar {
  background-color: var(--recife-navy) !important;
  border-bottom: none;
}
/* Logo do Cenarios (PNG transparente, texto azul + contorno terracota --
   feito pra fundo claro) sobre uma "etiqueta" branca, senao some no azul */
.main-header .logo-cenarios {
  background: var(--cen-superficie);
  border-radius: 6px;
  padding: 2px;
}
.main-header.navbar h4 {
  font-family: 'Poppins', 'Helvetica Neue', Arial, sans-serif;
  font-weight: 700 !important;
  color: #FFFFFF !important;
}

/* Texto branco nos titulos das caixas com cabecalho solido "primary"
   (barra navy: Mapa de casos, Tabela de casos). So' nas solidas -- a
   caixa de Filtros (card-outline, cabecalho transparente) ficava com o
   titulo branco sobre branco. */
.card.bg-primary > .card-header,
.card-primary:not(.card-outline) > .card-header,
.card.bg-primary .card-title,
.card-primary:not(.card-outline) .card-title,
.card.bg-primary .card-header i,
.card-primary:not(.card-outline) .card-header i {
  color: #FFF !important;
}
.card-primary > .card-header .card-title {
  font-size: 20px;
}
/* Caixas so' com borda (Filtros): titulo em azul titulos do guia */
.card-primary.card-outline > .card-header .card-title,
.card-primary.card-outline > .card-header i {
  color: var(--cen-azul-texto) !important;
}

/* Botoes de acao: azul acao do guia */
.btn-primary,
.btn-primary:not(:disabled):not(.disabled):active {
  background-color: var(--cen-azul-acao) !important;
  border-color: var(--cen-azul-acao) !important;
  color: #FFF !important;
}
.btn-primary:hover,
.btn-primary:focus {
  background-color: var(--cen-azul-texto) !important;
  border-color: var(--cen-azul-texto) !important;
}

a {
  color: var(--cen-azul-acao);
}

/* Cards de estatistica (topo): superficie branca, numero do KPI em
   DM Sans 700 escuro (32-40 px / 1.15), barra lateral na cor do indicador.
   A cor de cada card vem da classe bg-gradient-* que o bs4ValueBox gera a
   partir do argumento `color` (ver R/mod_municipio.R). */
.small-box {
  background: var(--cen-superficie) !important;
  background-image: none !important;
  border: 1px solid var(--cen-linha);
  border-left: 5px solid var(--cen-card-cor, var(--cen-azul));
  border-radius: 8px;
  box-shadow: none !important;
}
.small-box.bg-gradient-teal    { --cen-card-cor: var(--cen-s1); }       /* Total de casos */
.small-box.bg-gradient-warning { --cen-card-cor: var(--cen-azul-acao); } /* Casos em aberto */
.small-box.bg-gradient-success { --cen-card-cor: var(--cen-ok); }        /* Curados */
.small-box.bg-gradient-danger  { --cen-card-cor: var(--cen-critico); }   /* Obitos por TB */
.small-box.bg-gradient-orange  { --cen-card-cor: var(--cen-grave); }     /* Abandono/falencia */
.small-box.bg-gradient-purple  { --cen-card-cor: var(--cen-s3); }        /* TB-DR */
.small-box.bg-gradient-indigo  { --cen-card-cor: var(--cen-s7); }        /* Situacao de rua */
.small-box.bg-gradient-maroon  { --cen-card-cor: var(--cen-s5); }        /* Privado de liberdade */

.small-box .inner h3 {
  font-family: 'DM Sans', 'Helvetica Neue', Arial, sans-serif;
  font-weight: 700 !important;
  font-size: 34px;
  line-height: 1.15;
  color: var(--cen-tinta) !important;
}
.small-box .inner h5,
.small-box .inner p {
  font-family: 'DM Sans', 'Helvetica Neue', Arial, sans-serif;
  font-weight: 400 !important;
  font-size: 15px;
  color: var(--cen-tinta-2) !important;
}
.small-box .icon > i {
  color: var(--cen-card-cor, var(--cen-azul)) !important;
  opacity: 0.25;
}
.small-box .small-box-footer {
  background: var(--cen-azul-fundo) !important;
  color: var(--cen-azul-acao) !important;
  border-radius: 0 0 8px 0;
}

/* Cards de estatistica com altura igual entre si -- exceto o card
   "Casos em aberto" (bg-gradient-warning), que tem rodape proprio e fica
   com a altura automatica original. */
.small-box:not(.bg-gradient-warning) {
  height: 115px !important;
  display: flex !important;
  flex-direction: column !important;
}
.small-box:not(.bg-gradient-warning) > .inner {
  flex: 1 1 auto;
}
.small-box:not(.bg-gradient-warning) .small-box-footer {
  margin-top: auto;
}

/* Mapa: legenda e rotulos em DM Sans 400 12-13 px (eixo/legenda do guia) */
.info.legend {
  font-size: 12px;
  line-height: 1.4;
  color: var(--cen-tinta-3);
}
.info.legend strong,
.info.legend .legend-title {
  color: var(--cen-tinta);
}
.leaflet-tooltip {
  font-family: 'DM Sans', 'Helvetica Neue', Arial, sans-serif;
  color: var(--cen-tinta-2);
}
.leaflet-control-layers {
  font-family: 'DM Sans', 'Helvetica Neue', Arial, sans-serif;
  font-size: 13px;
  color: var(--cen-tinta-2);
}

/* Tabelas (reactable): cabecalho em tinta escura, linhas da paleta */
.rt-th {
  color: var(--cen-tinta);
  font-weight: 700;
}
.rt-tr-header,
.rt-td {
  border-color: var(--cen-linha) !important;
}
.rt-page-button-current {
  background-color: var(--cen-azul-fundo) !important;
  color: var(--cen-azul-acao) !important;
  font-weight: 700;
}
.rt-search,
.rt-filter,
.rt-page-jump,
.rt-page-size-select {
  border-color: var(--cen-linha) !important;
}

/* ==========================================================================
   Controles (filtros, recorte, datas) -- azul acao do guia no estado
   ativo/selecionado; bordas e fundos da paleta
   ========================================================================== */

/* Radio/checkbox nativos (recorte Bairro/DS, selecao da tabela de desfechos) */
input[type="radio"],
input[type="checkbox"] {
  accent-color: var(--cen-azul-acao);
}

/* Botoes secundarios (Abrir filtros, Limpar filtros): contorno azul acao */
.btn-secondary {
  background-color: var(--cen-superficie) !important;
  color: var(--cen-azul-acao) !important;
  border: 1px solid var(--cen-azul-acao) !important;
}
.btn-secondary:hover,
.btn-secondary:focus {
  background-color: var(--cen-azul-fundo) !important;
}

/* Grupo de botoes do filtro de Sexo (checkboxGroupButtons status "info"):
   selecionado = azul acao cheio; nao selecionado = contorno */
.btn-info,
.btn-info.active,
.btn-info:not(:disabled):not(.disabled).active {
  background-color: var(--cen-azul-acao) !important;
  border-color: var(--cen-azul-acao) !important;
  color: #FFF !important;
}
.btn-group-toggle .btn-info:not(.active) {
  background-color: var(--cen-superficie) !important;
  color: var(--cen-azul-acao) !important;
}

/* Caixa "Mostrar indicador no mapa" (prettyCheckbox status "info") */
.pretty input:checked ~ .state.p-info label:after,
.pretty.p-toggle .state.p-info label:after {
  background-color: var(--cen-azul-acao) !important;
}

/* Slider de idade (ionRangeSlider, skin "shiny") */
.irs--shiny .irs-bar {
  background: var(--cen-azul-acao);
  border-top-color: var(--cen-azul-acao);
  border-bottom-color: var(--cen-azul-acao);
}
.irs--shiny .irs-from,
.irs--shiny .irs-to,
.irs--shiny .irs-single {
  background-color: var(--cen-azul-acao);
  font-variant-numeric: tabular-nums;
}
.irs--shiny .irs-from:before,
.irs--shiny .irs-to:before,
.irs--shiny .irs-single:before {
  border-top-color: var(--cen-azul-acao);
}
.irs--shiny .irs-handle {
  border-color: var(--cen-azul-acao);
}
.irs--shiny .irs-min,
.irs--shiny .irs-max,
.irs--shiny .irs-grid-text {
  color: var(--cen-tinta-3);
}

/* Calendario do filtro de periodo (bootstrap-datepicker) */
.datepicker table tr td.active,
.datepicker table tr td.active:hover,
.datepicker table tr td.active.active,
.datepicker table tr td span.active {
  background-color: var(--cen-azul-acao) !important;
  background-image: none !important;
  color: #FFF !important;
}
.datepicker table tr td.today {
  background-color: var(--cen-terra-fundo) !important;
  background-image: none !important;
}

/* Listas de selecao (pickerInput / selectInput) */
.bootstrap-select .dropdown-menu li.selected a,
.bootstrap-select .dropdown-menu li a:active,
.dropdown-item.active,
.dropdown-item:active,
.selectize-dropdown .active {
  background-color: var(--cen-azul-fundo) !important;
  color: var(--cen-azul-texto) !important;
}

/* Foco dos campos */
.form-control:focus,
.selectize-input.focus,
.bootstrap-select .dropdown-toggle:focus {
  border-color: var(--cen-azul) !important;
  box-shadow: 0 0 0 0.2rem rgba(56, 145, 192, 0.25) !important;
}

/* Rotulos dos campos */
.control-label,
.content-wrapper label {
  color: var(--cen-tinta);
}

/* Popup dos pontos de caso no mapa */
.leaflet-popup-content {
  font-family: 'DM Sans', 'Helvetica Neue', Arial, sans-serif;
  font-size: 13px;
  line-height: 1.5;
  color: var(--cen-tinta-2);
}
.leaflet-popup-content b {
  color: var(--cen-tinta);
}

/* Notificacoes (atualizacao de dados etc.): barra lateral na cor de estado */
.shiny-notification {
  font-family: 'DM Sans', 'Helvetica Neue', Arial, sans-serif;
  border-left: 5px solid var(--cen-azul);
}
.shiny-notification-error {
  border-left-color: var(--cen-critico);
}
.shiny-notification-warning {
  border-left-color: var(--cen-atencao);
}

/* Indicador de carregamento no mapa e na tabela de casos (classe
   "saida-carregando" num div em volta da saida, em R/mod_municipio.R):
   enquanto o servidor recalcula, o Shiny marca a saida com .recalculating
   -- esmaece o conteudo e mostra um anel girando no centro, no azul acao
   do guia. So' aparece se o recalculo passar de 0,4 s, pra nao piscar nas
   trocas rapidas. */
.saida-carregando > .shiny-bound-output {
  position: relative;
}
.saida-carregando > .recalculating {
  opacity: 0.55 !important;
}
/* O mapa nao e' mais recalculado como um todo -- as camadas sao
   atualizadas por leafletProxy e a saida nunca fica .recalculating. Nele
   (classe "saida-carregando-ocupado") o indicador segue o estado "ocupado"
   do servidor (html.shiny-busy), com o mesmo atraso de 0,4 s. */
html.shiny-busy .saida-carregando-ocupado > .shiny-bound-output {
  opacity: 0.55;
  transition: opacity 0.2s ease 0.4s;
}
.saida-carregando > .recalculating::after,
html.shiny-busy .saida-carregando-ocupado > .shiny-bound-output::after {
  content: "";
  position: absolute;
  top: 50%;
  left: 50%;
  width: 44px;
  height: 44px;
  margin: -22px 0 0 -22px;
  border: 4px solid var(--cen-azul-fundo);
  border-top-color: var(--cen-azul-acao);
  border-radius: 50%;
  z-index: 1100; /* acima dos paineis e controles do Leaflet */
  animation: cen-gira 0.8s linear infinite, cen-surge 0.2s ease 0.4s both;
}
@keyframes cen-gira {
  to { transform: rotate(360deg); }
}
@keyframes cen-surge {
  from { opacity: 0; }
  to { opacity: 1; }
}

